constraints:
1 ≤ K ≤ N ≤ 10^{5} 
-10^{4} ≤ X, arr[i] ≤ 10^{4}

expected time complexity: O(NlogN)
expected auxiliary space: O(N)

standard_solution_code:
import heapq

class Solution:

	def Kclosest(self, arr, n, x, k):
		maxheap = []
		ans = []
		for i in range(0, n):
			diff = abs(arr[i] - x)
			heapq.heappush(maxheap, (-diff, -arr[i]))
		while len(maxheap) > k:
			heapq.heappop(maxheap)
		while len(maxheap) > 0:
			ele = heapq.heappop(maxheap)
			ans.append(ele[1] * -1)
		ans.sort()
		return ans
